import { useEffect, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import {
  Activity, ArrowRight, BadgeCheck, Bell, Camera, Check, ChevronDown, ChevronRight, CircleDot,
  ClipboardList, Cloud, Cpu, Database, Eye, Facebook, FileText, Gauge, Globe2, HardDrive, Headphones, Image,
  Instagram, Laptop, Lock, LogOut, Mail, MapPin, Menu, MessageCircle, Monitor, Moon, Network, Package, Phone,
  Plus, Quote, Save, Send, Server, Settings, ShieldCheck, Smartphone, Star, Sun, Target, Trash2, TrendingUp,
  User, Video, Wifi, Wrench, X, Youtube, Zap
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { fallbackSettings, type CctvCategory, type CctvProduct, type Enquiry, type Faq, type LaptopService, type NewsItem, type Service, type SiteSettings, type Testimonial } from '@/supabase/types';

type Page = 'home' | 'services' | 'cctv' | 'laptop' | 'networking' | 'domain' | 'os' | 'about' | 'contact';
type AdminView = 'dashboard' | 'settings' | 'services' | 'products' | 'categories' | 'laptop' | 'enquiries' | 'news' | 'media' | 'testimonials' | 'faqs';

const iconMap: Record<string, LucideIcon> = { Activity, Camera, CircleDot, Cloud, Cpu, Database, Globe2, HardDrive, Headphones, Laptop, Lock, Monitor, Moon, Network, Package, Server, Settings, ShieldCheck, Smartphone, Sun, Target, User, Video, Wifi, Wrench, Zap };
const img = 'https://images.pexels.com/photos/';

const fallbackServices: Service[] = [
  { id:'1', title:'IT Services', slug:'it-services', short_description:'Reliable IT support that keeps your business moving.', long_description:'IT Support, AMC & Maintenance, Remote Support and On-site Support for homes and businesses.', icon:'Headphones', image:img+'37605911/pexels-photo-37605911.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', features:['IT Support','AMC & Maintenance','Remote Support','On-site Support'], category:'core', sort_order:1, is_published:true },
  { id:'2', title:'IT Networking', slug:'it-networking', short_description:'Build faster, more reliable networks.', long_description:'LAN/WAN setup, network configuration, structured cabling and Wi-Fi solutions.', icon:'Network', image:img+'2881232/pexels-photo-2881232.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', features:['LAN/WAN Setup','Network Configuration','Structured Cabling','Wi-Fi Solutions'], category:'core', sort_order:2, is_published:true },
  { id:'3', title:'Firewall & Security', slug:'firewall-security', short_description:'Defend your business from digital threats.', long_description:'Firewall setup, network security, threat protection and secure VPN configuration.', icon:'ShieldCheck', image:img+'5483248/pexels-photo-5483248.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', features:['Firewall Setup','Network Security','Threat Protection','VPN'], category:'core', sort_order:3, is_published:true },
  { id:'4', title:'CCTV Surveillance', slug:'cctv-surveillance', short_description:'See more. Worry less. Stay protected.', long_description:'Professional CCTV installation, IP and analog cameras, remote viewing and AMC.', icon:'Camera', image:img+'5966513/pexels-photo-5966513.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', features:['CCTV Installation','IP Cameras','Remote Viewing','AMC'], category:'core', sort_order:4, is_published:true },
  { id:'5', title:'Server Setup', slug:'server-setup', short_description:'Infrastructure built for dependable performance.', long_description:'Server installation, configuration, backup solutions and maintenance.', icon:'Server', image:img+'37730212/pexels-photo-37730212.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', features:['Server Installation','Configuration','Backup Solutions','Maintenance'], category:'core', sort_order:5, is_published:true },
  { id:'6', title:'Software Installation', slug:'software-installation', short_description:'Get every system ready for work.', long_description:'Windows, MS Office, Tally, accounting software and complete system setup.', icon:'Monitor', image:img+'256502/pexels-photo-256502.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', features:['Windows','MS Office','Tally','System Configuration'], category:'core', sort_order:6, is_published:true },
  { id:'7', title:'Hardware Installation', slug:'hardware-installation', short_description:'Powerful hardware, installed properly.', long_description:'Computer setup, hardware upgrades, peripheral setup and system installation.', icon:'Cpu', image:img+'10558599/pexels-photo-10558599.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', features:['Computer Setup','Hardware Upgrade','Peripheral Setup','System Installation'], category:'core', sort_order:7, is_published:true },
  { id:'8', title:'Laptop Repair', slug:'laptop-repair', short_description:'Expert care for every laptop problem.', long_description:'Laptop repair, screen replacement, hardware and software repair, SSD and RAM upgrades.', icon:'Laptop', image:img+'7639374/pexels-photo-7639374.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', features:['Laptop Repair','Screen Replacement','SSD Upgrade','RAM Upgrade'], category:'core', sort_order:8, is_published:true },
];

const fallbackCategories: CctvCategory[] = ['Solar Cameras','Wi-Fi Cameras','Wired Cameras','IP Cameras','Dome Cameras','Bullet Cameras','PTZ Cameras','Night Vision Cameras','4G Cameras'].map((name, i) => ({ id:String(i), name, slug:name.toLowerCase().replace(/ /g,'-'), icon:['Sun','Wifi','Network','Globe2','CircleDot','Camera','Activity','Moon','Signal'][i] ?? 'Camera', description:'Professional surveillance for every space.', image:[img+'96612/pexels-photo-96612.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',img+'5589597/pexels-photo-5589597.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',img+'430208/pexels-photo-430208.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'][i%3], sort_order:i+1, is_published:true }));

function App() {
  const [page, setPage] = useState<Page>('home');
  const [adminView, setAdminView] = useState<AdminView>('dashboard');
  const [settings, setSettings] = useState<SiteSettings>(fallbackSettings);
  const [services, setServices] = useState<Service[]>(fallbackServices);
  const [categories, setCategories] = useState<CctvCategory[]>(fallbackCategories);
  const [products, setProducts] = useState<CctvProduct[]>([]);
  const [laptopServices, setLaptopServices] = useState<LaptopService[]>([]);
  const [enquiries, setEnquiries] = useState<Enquiry[]>([]);
  const [news, setNews] = useState<NewsItem[]>([]);
  const [testimonials, setTestimonials] = useState<Testimonial[]>([]);
  const [faqs, setFaqs] = useState<Faq[]>([]);
  const [session, setSession] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [quoteOpen, setQuoteOpen] = useState(false);

  useEffect(() => {
    let active = true;
    const load = async () => {
      const [settingsRes, servicesRes, catsRes, productsRes, laptopRes, newsRes, testimonialsRes, faqsRes] = await Promise.all([
        supabase.from('site_settings').select('*').eq('id',1).maybeSingle(), supabase.from('services').select('*').eq('is_published',true).order('sort_order'), supabase.from('cctv_categories').select('*').eq('is_published',true).order('sort_order'), supabase.from('cctv_products').select('*').eq('is_published',true).order('sort_order'), supabase.from('laptop_services').select('*').eq('is_published',true).order('sort_order'), supabase.from('news').select('*').eq('is_published',true).order('news_date',{ascending:false}), supabase.from('testimonials').select('*').eq('is_published',true).order('sort_order'), supabase.from('faqs').select('*').eq('is_published',true).order('sort_order')
      ]);
      if (!active) return;
      if (settingsRes.data) setSettings(settingsRes.data as SiteSettings);
      if (servicesRes.data?.length) setServices(servicesRes.data as Service[]);
      if (catsRes.data?.length) setCategories(catsRes.data as CctvCategory[]);
      if (productsRes.data) setProducts(productsRes.data as CctvProduct[]);
      if (laptopRes.data) setLaptopServices(laptopRes.data as LaptopService[]);
      if (newsRes.data) setNews(newsRes.data as NewsItem[]);
      if (testimonialsRes.data) setTestimonials(testimonialsRes.data as Testimonial[]);
      if (faqsRes.data) setFaqs(faqsRes.data as Faq[]);
    };
    void load();
    const { data } = supabase.auth.onAuthStateChange((_event, currentSession) => { setSession(Boolean(currentSession)); });
    void supabase.auth.getSession().then(({ data: sessionData }) => { if (active) setSession(Boolean(sessionData.session)); });
    return () => { active = false; data.subscription.unsubscribe(); };
  }, []);

  const navigate = (next: Page) => { setPage(next); setMenuOpen(false); window.scrollTo({ top:0, behavior:'smooth' }); };
  const openAdmin = () => { setPage('home'); setAdminView('dashboard'); window.history.pushState({}, '', '/admin'); };
  const [isAdmin, setIsAdmin] = useState(window.location.pathname.startsWith('/admin'));
  useEffect(() => { const onPop = () => setIsAdmin(window.location.pathname.startsWith('/admin')); window.addEventListener('popstate', onPop); return () => window.removeEventListener('popstate', onPop); }, []);
  if (isAdmin) return <AdminApp settings={settings} setSettings={setSettings} services={services} setServices={setServices} products={products} setProducts={setProducts} categories={categories} setCategories={setCategories} laptopServices={laptopServices} setLaptopServices={setLaptopServices} enquiries={enquiries} setEnquiries={setEnquiries} news={news} setNews={setNews} testimonials={testimonials} setTestimonials={setTestimonials} faqs={faqs} setFaqs={setFaqs} adminView={adminView} setAdminView={setAdminView} session={session} setSession={setSession} />;

  return <div className="min-h-screen bg-[#f7fafc] text-[#122034]">
    <Header settings={settings} page={page} navigate={navigate} menuOpen={menuOpen} setMenuOpen={setMenuOpen} onQuote={() => setQuoteOpen(true)} />
    <main>
      {page === 'home' && <HomePage settings={settings} services={services} categories={categories} testimonials={testimonials} news={news} faqs={faqs} navigate={navigate} onQuote={() => setQuoteOpen(true)} />}
      {page === 'services' && <ServicesPage services={services} navigate={navigate} onQuote={() => setQuoteOpen(true)} />}
      {page === 'cctv' && <CctvPage settings={settings} categories={categories} products={products} onQuote={() => setQuoteOpen(true)} />}
      {page === 'laptop' && <LaptopPage settings={settings} laptopServices={laptopServices} onQuote={() => setQuoteOpen(true)} />}
      {page === 'networking' && <NetworkingPage settings={settings} onQuote={() => setQuoteOpen(true)} />}
      {page === 'domain' && <InfoPage type="domain" settings={settings} onQuote={() => setQuoteOpen(true)} />}
      {page === 'os' && <InfoPage type="os" settings={settings} onQuote={() => setQuoteOpen(true)} />}
      {page === 'about' && <AboutPage settings={settings} testimonials={testimonials} />}
      {page === 'contact' && <ContactPage settings={settings} />}
    </main>
    <Footer settings={settings} navigate={navigate} onAdmin={openAdmin} />
    <MobileActions settings={settings} />
    {quoteOpen && <QuoteModal services={services} onClose={() => setQuoteOpen(false)} />}
  </div>;
}

function Header({ settings, page, navigate, menuOpen, setMenuOpen, onQuote }: { settings: SiteSettings; page: Page; navigate:(p:Page)=>void; menuOpen:boolean; setMenuOpen:(v:boolean)=>void; onQuote:()=>void }) {
  const links: {label:string; value:Page}[] = [{label:'Home',value:'home'},{label:'Services',value:'services'},{label:'CCTV',value:'cctv'},{label:'Laptop Repair',value:'laptop'},{label:'Networking',value:'networking'},{label:'About',value:'about'}];
  const goAdmin = () => { window.history.pushState({}, '', '/admin'); window.dispatchEvent(new PopStateEvent('popstate')); };
  return <><div className="bg-[#071a35] text-white text-[11px] tracking-[.18em] uppercase"><div className="container flex min-h-9 items-center justify-between"><span className="hidden sm:block">{settings.tagline}</span><span className="flex items-center gap-4"><a href={`tel:${settings.phone}`} className="hover:text-cyan-300">{settings.phone}</a><span className="hidden sm:inline text-white/30">|</span><a href={`mailto:${settings.email}`} className="hidden sm:inline hover:text-cyan-300">{settings.email}</a></span></div></div><header className="sticky top-0 z-40 border-b border-slate-200/80 bg-white/95 backdrop-blur"><div className="container flex h-[76px] items-center justify-between"><button onClick={()=>navigate('home')} className="flex items-center gap-3 text-left"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#0d55bb] text-white shadow-lg shadow-blue-200"><ShieldCheck size={25}/></span><span><span className="heading block text-[19px] font-bold tracking-tight text-[#071a35]">{settings.business_name}</span><span className="block text-[9px] font-semibold tracking-[.18em] text-[#0d55bb]">IT • SECURITY • NETWORKS</span></span></button><nav className="hidden items-center gap-6 lg:flex">{links.map(link=><button key={link.value} onClick={()=>navigate(link.value)} className={`text-sm font-semibold transition-colors hover:text-[#0d55bb] ${page===link.value?'text-[#0d55bb]':'text-slate-600'}`}>{link.label}</button>)}<button onClick={()=>navigate('contact')} className="text-sm font-semibold text-slate-600 hover:text-[#0d55bb]">Contact</button><button onClick={goAdmin} className="flex items-center gap-1.5 rounded-lg border border-slate-200 px-4 py-3 text-sm font-bold text-[#071a35] transition hover:border-[#0d55bb] hover:text-[#0d55bb]"><Lock size={15}/> Admin</button><button onClick={onQuote} className="rounded-lg bg-[#0d55bb] px-5 py-3 text-sm font-bold text-white shadow-lg shadow-blue-200 transition hover:-translate-y-0.5 hover:bg-[#083f8d]">Get a quote <ArrowRight size={15} className="ml-1 inline"/></button></nav><button onClick={()=>setMenuOpen(!menuOpen)} className="rounded-lg p-2 text-[#071a35] lg:hidden">{menuOpen?<X/>:<Menu/>}</button></div>{menuOpen&&<nav className="container grid gap-1 border-t border-slate-100 pb-4 pt-3 lg:hidden">{links.concat({label:'Contact',value:'contact'}).map(link=><button key={link.value} onClick={()=>navigate(link.value)} className="rounded-lg px-3 py-3 text-left text-sm font-semibold text-slate-700 hover:bg-slate-50">{link.label}</button>)}<button onClick={onQuote} className="mt-2 rounded-lg bg-[#0d55bb] px-4 py-3 text-sm font-bold text-white">Get a quote</button><button onClick={goAdmin} className="mt-1 flex items-center justify-center gap-1.5 rounded-lg border border-slate-200 px-4 py-3 text-sm font-bold text-[#071a35]"><Lock size={15}/> Admin</button></nav>}</header></>;
}

function HomePage({ settings, services, categories, testimonials, news, faqs, navigate, onQuote }: { settings:SiteSettings; services:Service[]; categories:CctvCategory[]; testimonials:Testimonial[]; news:NewsItem[]; faqs:Faq[]; navigate:(p:Page)=>void; onQuote:()=>void }) {
  return <><section className="relative overflow-hidden bg-[#071a35] text-white"><div className="absolute inset-0 bg-cover bg-center opacity-35" style={{backgroundImage:`url(${settings.hero_image})`}}/><div className="absolute inset-0 bg-gradient-to-r from-[#071a35] via-[#071a35]/90 to-[#071a35]/25"/><div className="grid-pattern absolute inset-0 opacity-30"/><div className="container relative grid min-h-[650px] items-center gap-14 py-24 lg:grid-cols-[1.05fr_.95fr]"><div className="max-w-2xl"><div className="mb-7 inline-flex items-center gap-2 rounded-full border border-cyan-300/30 bg-cyan-300/10 px-4 py-2 text-[11px] font-bold tracking-[.2em] text-cyan-200"><span className="h-2 w-2 rounded-full bg-cyan-300"/> HYDERABAD'S TRUSTED TECH PARTNER</div><h1 className="heading text-5xl font-bold leading-[1.05] tracking-tight sm:text-6xl lg:text-7xl">{settings.hero_title}<span className="block text-cyan-300">{settings.hero_subtitle}</span></h1><p className="mt-7 max-w-xl text-lg leading-8 text-slate-300">{settings.hero_description}</p><div className="mt-9 flex flex-wrap gap-3"><button onClick={onQuote} className="rounded-lg bg-[#0d55bb] px-6 py-4 text-sm font-bold text-white shadow-xl shadow-blue-950/30 transition hover:-translate-y-1 hover:bg-[#1768d6]">Get a quote <ArrowRight size={16} className="ml-2 inline"/></button><a href={`https://wa.me/${settings.whatsapp}`} target="_blank" rel="noreferrer" className="rounded-lg border border-white/20 bg-white/10 px-6 py-4 text-sm font-bold text-white backdrop-blur transition hover:bg-white/20"><MessageCircle size={16} className="mr-2 inline text-[#54d66a]"/> WhatsApp</a><a href={`tel:${settings.phone}`} className="rounded-lg border border-white/20 px-6 py-4 text-sm font-bold text-white transition hover:bg-white/10"><Phone size={16} className="mr-2 inline"/> Call now</a></div><div className="mt-12 flex flex-wrap gap-x-8 gap-y-3 text-sm text-slate-300"><span><BadgeCheck size={17} className="mr-2 inline text-cyan-300"/>Experienced team</span><span><BadgeCheck size={17} className="mr-2 inline text-cyan-300"/>Genuine solutions</span><span><BadgeCheck size={17} className="mr-2 inline text-cyan-300"/>Fast response</span></div></div><div className="hidden lg:block"><div className="relative ml-auto max-w-md"><div className="absolute -inset-5 rounded-3xl border border-cyan-300/20"/><div className="relative overflow-hidden rounded-2xl border border-white/15 bg-white/10 p-3 shadow-2xl backdrop-blur"><img src={settings.hero_image} alt="MS INFOTECH server infrastructure" className="h-[360px] w-full rounded-xl object-cover"/><div className="absolute bottom-8 left-8 right-8 flex items-center justify-between rounded-xl bg-[#071a35]/90 p-4 backdrop-blur"><span><span className="block text-[10px] tracking-[.18em] text-cyan-300">SERVICE PROMISE</span><span className="mt-1 block font-semibold">Secure. Scalable. Supported.</span></span><span className="flex h-10 w-10 items-center justify-center rounded-full bg-cyan-300 text-[#071a35]"><ArrowRight size={19}/></span></div></div></div></div></div></section><TrustStrip/><section className="section-pad bg-white"><div className="container"><SectionIntro eyebrow="WHAT WE DO" title="Everything your technology needs." desc="From a single laptop to an entire business network, MS INFOTECH delivers dependable technology with a human touch." action="View all services" onAction={()=>navigate('services')}/><div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{services.slice(0,8).map((service,i)=><ServiceCard key={service.id} service={service} featured={i===3} onClick={()=>service.slug==='cctv-surveillance'?navigate('cctv'):service.slug==='laptop-repair'?navigate('laptop'):service.slug==='it-networking'?navigate('networking'):undefined}/>)}</div></div></section><section className="section-pad bg-[#eff6ff]"><div className="container grid items-center gap-12 lg:grid-cols-[.9fr_1.1fr]"><div className="relative"><img src={settings.about_image} alt="IT professional managing infrastructure" className="h-[450px] w-full rounded-2xl object-cover shadow-card"/><div className="absolute -bottom-5 -right-5 rounded-xl bg-white p-5 shadow-xl"><div className="flex items-center gap-3"><span className="flex h-11 w-11 items-center justify-center rounded-lg bg-[#dff7ec] text-[#16834c]"><ShieldCheck size={23}/></span><span><b className="block text-2xl text-[#071a35]">10+</b><small className="text-slate-500">years of trust</small></span></div></div></div><div><SectionIntro eyebrow="WHY MS INFOTECH" title={settings.about_title} desc={settings.about_description}/><div className="mt-8 grid gap-4 sm:grid-cols-2">{['Professional service','Quality products','Transparent pricing','Local support'].map((item)=><div key={item} className="flex items-center gap-3 rounded-xl bg-white p-4 shadow-sm"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#e4f1ff] text-[#0d55bb]"><Check size={16}/></span><span className="font-semibold text-[#18304f]">{item}</span></div>)}</div><button onClick={()=>navigate('about')} className="mt-8 rounded-lg border border-[#0d55bb] px-5 py-3 text-sm font-bold text-[#0d55bb] hover:bg-[#0d55bb] hover:text-white">More about us <ArrowRight size={15} className="ml-2 inline"/></button></div></div></section><CctvFeature settings={settings} categories={categories} navigate={navigate} onQuote={onQuote}/><LaptopFeature settings={settings} navigate={navigate} onQuote={onQuote}/><section className="section-pad bg-[#071a35] text-white"><div className="container grid gap-12 lg:grid-cols-[.85fr_1.15fr] lg:items-center"><div><SectionIntro dark eyebrow="BUILT FOR BUSINESS" title={settings.networking_section_title} desc="From structured cabling to Windows Server and Active Directory, we create infrastructure that works quietly and reliably behind your business."/><div className="mt-8 grid grid-cols-2 gap-3">{['LAN / WAN setup','Router & switch config','Wi-Fi installation','Firewall & VPN','Windows Server','Active Directory'].map(item=><div key={item} className="flex items-center gap-2 text-sm text-slate-300"><Check size={15} className="text-cyan-300"/>{item}</div>)}</div><button onClick={()=>navigate('networking')} className="mt-8 rounded-lg bg-cyan-300 px-5 py-3 text-sm font-bold text-[#071a35] hover:bg-white">Explore networking <ArrowRight size={15} className="ml-2 inline"/></button></div><div className="relative"><img src={img+'2881229/pexels-photo-2881229.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'} alt="Network cabling" className="h-[340px] w-full rounded-2xl object-cover opacity-85"/><div className="absolute inset-0 rounded-2xl bg-gradient-to-t from-[#071a35] to-transparent"/><div className="absolute bottom-6 left-6 flex items-center gap-3"><span className="flex h-12 w-12 items-center justify-center rounded-xl bg-cyan-300 text-[#071a35]"><Network/></span><span><b className="block">Connected infrastructure</b><small className="text-slate-300">Designed for your next step</small></span></div></div></div></section><TestimonialSection testimonials={testimonials}/><NewsSection news={news}/><FaqSection faqs={faqs}/><CtaBand onQuote={onQuote}/></>;
}

function TrustStrip(){return <div className="border-b border-slate-200 bg-white"><div className="container grid grid-cols-2 divide-x divide-slate-200 sm:grid-cols-4"><div className="flex items-center gap-3 px-3 py-5 sm:px-6"><span className="text-[#0d55bb]"><BadgeCheck/></span><span><b className="block text-sm">Trusted service</b><small className="text-xs text-slate-500">In Hyderabad</small></span></div><div className="flex items-center gap-3 px-3 py-5 sm:px-6"><span className="text-[#0d55bb]"><ClockIcon/></span><span><b className="block text-sm">Fast response</b><small className="text-xs text-slate-500">When you need us</small></span></div><div className="hidden items-center gap-3 px-6 py-5 sm:flex"><span className="text-[#0d55bb]"><ShieldCheck/></span><span><b className="block text-sm">Secure solutions</b><small className="text-xs text-slate-500">Built to last</small></span></div><div className="hidden items-center gap-3 px-6 py-5 sm:flex"><span className="text-[#0d55bb]"><Headphones/></span><span><b className="block text-sm">Ongoing support</b><small className="text-xs text-slate-500">Here for the journey</small></span></div></div></div>}
function ClockIcon(){return <Activity/>}
function SectionIntro({ eyebrow, title, desc, dark=false, action, onAction }: { eyebrow:string; title:string; desc:string; dark?:boolean; action?:string; onAction?:()=>void }){return <div className="max-w-2xl"><div className={`mb-4 flex items-center gap-3 text-[11px] font-bold tracking-[.2em] ${dark?'text-cyan-300':'text-[#0d55bb]'}`}><span className={`h-px w-8 ${dark?'bg-cyan-300':'bg-[#0d55bb]'}`}/>{eyebrow}</div><div className="flex flex-wrap items-end justify-between gap-5"><h2 className={`heading text-3xl font-bold leading-tight sm:text-4xl ${dark?'text-white':'text-[#071a35]'}`}>{title}</h2>{action&&onAction&&<button onClick={onAction} className="text-sm font-bold text-[#0d55bb] hover:underline">{action} <ArrowRight size={14} className="ml-1 inline"/></button>}</div><p className={`mt-4 max-w-xl leading-7 ${dark?'text-slate-300':'text-slate-600'}`}>{desc}</p></div>}
function ServiceCard({service, featured, onClick}:{service:Service; featured?:boolean; onClick?:()=>void}){const Icon=iconMap[service.icon]??Settings;return <button onClick={onClick} className={`group overflow-hidden rounded-xl border text-left transition hover:-translate-y-1 hover:shadow-card ${featured?'border-[#0d55bb] bg-[#0d55bb] text-white':'border-slate-200 bg-white text-[#122034]'}`}><div className="relative h-36 overflow-hidden"><img src={service.image} alt={service.title} className="h-full w-full object-cover transition duration-500 group-hover:scale-105"/><div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent"/><span className={`absolute bottom-3 left-3 flex h-10 w-10 items-center justify-center rounded-lg ${featured?'bg-cyan-300 text-[#071a35]':'bg-white text-[#0d55bb]'}`}><Icon size={20}/></span></div><div className="p-5"><h3 className="heading font-bold">{service.title}</h3><p className={`mt-2 text-sm leading-6 ${featured?'text-blue-100':'text-slate-500'}`}>{service.short_description}</p><span className={`mt-4 block text-xs font-bold ${featured?'text-cyan-200':'text-[#0d55bb]'}`}>Explore service <ChevronRight size={14} className="ml-1 inline transition group-hover:translate-x-1"/></span></div></button>}
function CctvFeature({settings,categories,navigate,onQuote}:{settings:SiteSettings;categories:CctvCategory[];navigate:(p:Page)=>void;onQuote:()=>void}){return <section className="section-pad bg-white"><div className="container grid items-center gap-12 lg:grid-cols-[1.1fr_.9fr]"><div className="relative order-2 lg:order-1"><div className="grid grid-cols-2 gap-4"><img src={categories[0]?.image} alt="Outdoor CCTV camera" className="h-64 w-full rounded-2xl object-cover"/><img src={categories[4]?.image} alt="Dome CCTV camera" className="mt-10 h-64 w-full rounded-2xl object-cover"/></div><div className="absolute bottom-4 left-1/2 flex -translate-x-1/2 items-center gap-3 rounded-xl bg-white px-5 py-3 shadow-xl"><span className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#e4f1ff] text-[#0d55bb]"><Eye size={19}/></span><span className="whitespace-nowrap text-sm font-bold">Mobile monitoring, anywhere</span></div></div><div className="order-1 lg:order-2"><SectionIntro eyebrow="SECURITY THAT WATCHES OVER WHAT MATTERS" title={settings.cctv_section_title} desc={settings.cctv_section_subtitle}/><div className="mt-8 grid grid-cols-2 gap-x-4 gap-y-3">{['HD & 4K surveillance','Mobile monitoring','Remote access anywhere','DVR & NVR solutions','Professional installation','Service & support'].map(item=><div key={item} className="flex items-center gap-2 text-sm font-semibold text-slate-700"><Check size={16} className="text-[#16834c]"/>{item}</div>)}</div><div className="mt-9 flex flex-wrap gap-3"><button onClick={()=>navigate('cctv')} className="rounded-lg bg-[#0d55bb] px-5 py-3 text-sm font-bold text-white hover:bg-[#083f8d]">View cameras</button><button onClick={onQuote} className="rounded-lg border border-slate-300 px-5 py-3 text-sm font-bold text-[#122034] hover:border-[#0d55bb] hover:text-[#0d55bb]">Get CCTV quote</button></div></div></div></section>}
function LaptopFeature({settings,navigate,onQuote}:{settings:SiteSettings;navigate:(p:Page)=>void;onQuote:()=>void}){return <section className="section-pad bg-[#eff6ff]"><div className="container grid items-center gap-12 lg:grid-cols-[.9fr_1.1fr]"><div><SectionIntro eyebrow="REPAIR • UPGRADE • REFRESH" title={settings.laptop_section_title} desc="Whether it's a cracked screen, slow performance or a complete system failure, our technicians bring your laptop back to life."/><h3 className="heading mt-7 text-2xl font-bold text-[#0d55bb]">{settings.laptop_section_subtitle}</h3><div className="mt-6 grid grid-cols-2 gap-3">{['Expert technicians','Genuine parts used','Quick turnaround','Affordable prices','Customer satisfaction','Clear diagnosis'].map(item=><div key={item} className="flex items-center gap-2 text-sm font-semibold text-slate-700"><Check size={16} className="text-[#0d55bb]"/>{item}</div>)}</div><div className="mt-8 flex gap-3"><button onClick={()=>navigate('laptop')} className="rounded-lg bg-[#0d55bb] px-5 py-3 text-sm font-bold text-white">Explore repairs</button><button onClick={onQuote} className="rounded-lg border border-[#0d55bb] px-5 py-3 text-sm font-bold text-[#0d55bb]">Book a repair</button></div></div><div className="relative"><img src={img+'7639374/pexels-photo-7639374.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'} alt="Laptop repair technician" className="h-[400px] w-full rounded-2xl object-cover shadow-card"/><div className="absolute -bottom-5 -left-5 rounded-xl bg-[#071a35] px-5 py-4 text-white shadow-xl"><span className="block text-[10px] tracking-[.18em] text-cyan-300">REPAIR DESK</span><span className="mt-1 block font-bold">We fix. You relax.</span></div></div></div></section>}
function TestimonialSection({testimonials}:{testimonials:Testimonial[]}){return <section className="section-pad bg-white"><div className="container"><SectionIntro eyebrow="CLIENT STORIES" title="Technology that earns trust." desc="A few words from the businesses and people we have helped."/><div className="mt-10 grid gap-5 md:grid-cols-3">{(testimonials.length?testimonials:[{id:'1',customer_name:'Our customers',rating:5,message:'Professional, responsive and dependable technology support.',image:'',is_published:true}]).slice(0,3).map(item=><div key={item.id} className="rounded-xl border border-slate-200 bg-slate-50 p-6"><Quote size={24} className="text-[#0d55bb]"/><p className="mt-4 text-sm leading-7 text-slate-600">“{item.message}”</p><div className="mt-6 flex items-center justify-between"><span className="font-bold text-[#071a35]">{item.customer_name}</span><span className="flex gap-0.5 text-amber-400">{Array.from({length:item.rating}).map((_,i)=><Star key={i} size={14} fill="currentColor"/>)}</span></div></div>)}</div></div></section>}
function NewsSection({news}:{news:NewsItem[]}){if(!news.length)return null;return <section className="section-pad bg-[#eff6ff]"><div className="container"><SectionIntro eyebrow="NEWS & UPDATES" title="Useful ideas for your technology." desc="Practical guidance and updates from the MS INFOTECH team."/><div className="mt-10 grid gap-5 md:grid-cols-2">{news.slice(0,2).map(item=><article key={item.id} className="grid overflow-hidden rounded-xl bg-white shadow-sm sm:grid-cols-[.8fr_1.2fr]"><img src={item.image} alt={item.title} className="h-48 w-full object-cover sm:h-full"/><div className="p-6"><span className="text-xs font-bold tracking-widest text-[#0d55bb]">{new Date(item.news_date).toLocaleDateString('en-IN',{month:'short',day:'numeric',year:'numeric'})}</span><h3 className="heading mt-3 text-xl font-bold text-[#071a35]">{item.title}</h3><p className="mt-3 text-sm leading-6 text-slate-500">{item.description}</p></div></article>)}</div></div></section>}
function FaqSection({faqs}:{faqs:Faq[]}){const [open,setOpen]=useState<string>(''); if(!faqs.length)return null; return <section className="section-pad bg-white"><div className="container grid gap-12 lg:grid-cols-[.75fr_1.25fr]"><SectionIntro eyebrow="FAQS" title="Answers, before you ask." desc="Still unsure where to start? Talk to our team and we will point you in the right direction."/><div className="divide-y divide-slate-200 border-y border-slate-200">{faqs.slice(0,4).map(item=><div key={item.id}><button onClick={()=>setOpen(open===item.id?'':item.id)} className="flex w-full items-center justify-between py-5 text-left font-bold text-[#18304f]"><span>{item.question}</span><ChevronDown size={18} className={`transition ${open===item.id?'rotate-180 text-[#0d55bb]':''}`}/></button>{open===item.id&&<p className="pb-5 text-sm leading-7 text-slate-600">{item.answer}</p>}</div>)}</div></div></section>}
function CtaBand({onQuote}:{onQuote:()=>void}){return <section className="bg-[#0d55bb] py-14 text-white"><div className="container flex flex-col items-start justify-between gap-7 sm:flex-row sm:items-center"><div><p className="text-sm font-bold tracking-[.18em] text-cyan-200">YOUR SECURITY IS OUR PRIORITY</p><h2 className="heading mt-2 text-3xl font-bold">Ready for a smarter setup?</h2></div><button onClick={onQuote} className="rounded-lg bg-white px-6 py-4 text-sm font-bold text-[#0d55bb] hover:bg-cyan-100">Talk to an expert <ArrowRight size={16} className="ml-2 inline"/></button></div></section>}

function ServicesPage({services,navigate,onQuote}:{services:Service[];navigate:(p:Page)=>void;onQuote:()=>void}){return <><PageHero eyebrow="OUR CAPABILITIES" title="Technology that works for you." desc="A complete range of IT, security and infrastructure services for homes, offices and growing businesses." image={services[1]?.image}/><section className="section-pad bg-white"><div className="container grid gap-6 md:grid-cols-2">{services.map(service=><ServiceCard key={service.id} service={service} onClick={()=>service.slug==='cctv-surveillance'?navigate('cctv'):service.slug==='laptop-repair'?navigate('laptop'):service.slug==='it-networking'?navigate('networking'):undefined}/>)}</div></section><CtaBand onQuote={onQuote}/></>}
function PageHero({eyebrow,title,desc,image}:{eyebrow:string;title:string;desc:string;image?:string}){return <section className="relative overflow-hidden bg-[#071a35] py-24 text-white"><div className="absolute inset-0 bg-cover bg-center opacity-25" style={{backgroundImage:`url(${image})`}}/><div className="absolute inset-0 bg-gradient-to-r from-[#071a35] to-[#071a35]/50"/><div className="container relative"><p className="text-xs font-bold tracking-[.22em] text-cyan-300">{eyebrow}</p><h1 className="heading mt-4 max-w-3xl text-5xl font-bold leading-tight sm:text-6xl">{title}</h1><p className="mt-5 max-w-2xl text-lg leading-8 text-slate-300">{desc}</p></div></section>}
function CctvPage({settings,categories,products,onQuote}:{settings:SiteSettings;categories:CctvCategory[];products:CctvProduct[];onQuote:()=>void}){return <><PageHero eyebrow="SMART SURVEILLANCE" title={settings.cctv_section_title} desc={settings.cctv_section_subtitle} image={categories[0]?.image}/><section className="section-pad bg-white"><div className="container"><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{categories.map(cat=>{const Icon=iconMap[cat.icon]??Camera;return <div key={cat.id} className="group overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:-translate-y-1 hover:shadow-card"><div className="h-44 overflow-hidden"><img src={cat.image} alt={cat.name} className="h-full w-full object-cover transition duration-500 group-hover:scale-105"/></div><div className="flex items-center gap-3 p-5"><span className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#e4f1ff] text-[#0d55bb]"><Icon size={19}/></span><div><h3 className="heading font-bold">{cat.name}</h3><p className="mt-1 text-xs text-slate-500">Professional installation available</p></div></div></div>})}</div></div></section><section className="section-pad bg-[#eff6ff]"><div className="container"><SectionIntro eyebrow="FEATURED EQUIPMENT" title="The right camera for every view." desc="Explore popular options from our CCTV range. Every product can be installed and configured by our team."/><div className="mt-10 grid gap-6 md:grid-cols-3">{products.length?products.map(product=><ProductCard key={product.id} product={product} onQuote={onQuote}/>):<div className="col-span-full rounded-xl bg-white p-10 text-center text-slate-500">Product catalog is being updated. Call us for current camera options.</div>}</div></div></section><CtaBand onQuote={onQuote}/></>}
function ProductCard({product,onQuote}:{product:CctvProduct;onQuote:()=>void}){return <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div className="relative h-52"><img src={product.image} alt={product.name} className="h-full w-full object-cover"/><span className="absolute left-4 top-4 rounded-full bg-[#16834c] px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-white">{product.stock_status.replace('_',' ')}</span></div><div className="p-5"><p className="text-xs font-bold tracking-wider text-[#0d55bb]">{product.brand} · {product.model}</p><h3 className="heading mt-2 text-lg font-bold text-[#071a35]">{product.name}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{product.description}</p><div className="mt-4 flex flex-wrap gap-2">{product.features.slice(0,3).map(feature=><span key={feature} className="rounded bg-slate-100 px-2 py-1 text-[11px] font-semibold text-slate-600">{feature}</span>)}</div><div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-4"><span className="text-lg font-bold text-[#071a35]">₹{(product.discount_price||product.price).toLocaleString('en-IN')}</span><button onClick={onQuote} className="rounded-lg bg-[#0d55bb] px-3 py-2 text-xs font-bold text-white">Enquire</button></div></div></div>}
function LaptopPage({settings,laptopServices,onQuote}:{settings:SiteSettings;laptopServices:LaptopService[];onQuote:()=>void}){return <><PageHero eyebrow="REPAIR • UPGRADE • RESTORE" title={`${settings.laptop_section_title} — ${settings.laptop_section_subtitle}`} desc="Expert technicians, genuine parts, quick turnaround and affordable prices for every laptop problem." image={settings.about_image}/><section className="section-pad bg-white"><div className="container grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{laptopServices.map(item=>{const Icon=iconMap[item.icon]??Laptop;return <div key={item.id} className="rounded-xl border border-slate-200 bg-white p-5 transition hover:-translate-y-1 hover:shadow-card"><span className="flex h-11 w-11 items-center justify-center rounded-lg bg-[#e4f1ff] text-[#0d55bb]"><Icon size={21}/></span><h3 className="heading mt-5 font-bold text-[#071a35]">{item.name}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{item.description}</p></div>})}</div></section><CtaBand onQuote={onQuote}/></>}
function NetworkingPage({settings,onQuote}:{settings:SiteSettings;onQuote:()=>void}){return <><PageHero eyebrow="INFRASTRUCTURE THAT CONNECTS" title={settings.networking_section_title} desc="Stable networks and reliable servers are the quiet foundation behind every productive business." image={img+'2881229/pexels-photo-2881229.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'}/><section className="section-pad bg-white"><div className="container grid gap-10 lg:grid-cols-2"><InfoBlock icon={Network} title="Networking solutions" items={['LAN / WAN setup','Router configuration','Switch configuration','Structured cabling','Wi-Fi installation','Firewall setup','VPN and remote access']}/><InfoBlock icon={Server} title="Server solutions" items={['Server installation','Server configuration','Windows Server','Active Directory','Domain setup','Backup solutions','Server maintenance']}/></div></section><CtaBand onQuote={onQuote}/></>}
function InfoBlock({icon:Icon,title,items}:{icon:LucideIcon;title:string;items:string[]}){return <div className="rounded-2xl bg-[#eff6ff] p-8"><span className="flex h-14 w-14 items-center justify-center rounded-xl bg-[#0d55bb] text-white"><Icon size={27}/></span><h2 className="heading mt-6 text-2xl font-bold text-[#071a35]">{title}</h2><div className="mt-6 grid gap-3 sm:grid-cols-2">{items.map(item=><div key={item} className="flex items-center gap-2 text-sm font-semibold text-slate-700"><Check size={16} className="text-[#16834c]"/>{item}</div>)}</div></div>}
function InfoPage({type,settings,onQuote}:{type:'domain'|'os';settings:SiteSettings;onQuote:()=>void}){const domain=type==='domain';const title=domain?settings.domain_section_title:settings.os_section_title;const items=domain?['Windows Domain Setup','Active Directory','User Management','Group Policy','Domain Controller','Server Configuration','Network Configuration','Security Configuration']:['Windows Installation','OS Installation','Driver Installation','Software Installation','MS Office Installation','Tally Installation','System Configuration','Troubleshooting','Data Backup'];return <><PageHero eyebrow={domain?'SERVER & IDENTITY':'SOFTWARE & SYSTEM CARE'} title={title} desc={domain?'Organize users, devices and access with a secure, professional business domain.':'Clean installations, correct drivers and a system configured for dependable everyday work.'} image={domain?img+'37730212/pexels-photo-37730212.jpeg?auto=compress&cs=tinysrgb&h=650&w=940':img+'256502/pexels-photo-256502.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'}/><section className="section-pad bg-white"><div className="container grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{items.map((item,i)=><div key={item} className="rounded-xl border border-slate-200 p-6 hover:border-[#0d55bb] hover:shadow-card"><span className="text-3xl font-bold text-[#cfe2fa]">0{i+1}</span><h3 className="heading mt-5 font-bold text-[#071a35]">{item}</h3><p className="mt-2 text-sm leading-6 text-slate-500">Professional setup with clear documentation and support.</p></div>)}</div></section><CtaBand onQuote={onQuote}/></>}
function AboutPage({settings,testimonials}:{settings:SiteSettings;testimonials:Testimonial[]}){return <><PageHero eyebrow="THE TEAM BEHIND THE SOLUTIONS" title="Technology with a personal touch." desc="MS INFOTECH is your local partner for dependable IT, security and infrastructure support in Hyderabad." image={settings.about_image}/><section className="section-pad bg-white"><div className="container grid items-center gap-12 lg:grid-cols-2"><img src={settings.about_image} alt="MS INFOTECH team at work" className="h-[450px] w-full rounded-2xl object-cover"/><div><SectionIntro eyebrow="OUR PROMISE" title={settings.about_title} desc={settings.about_description}/><div className="mt-8 space-y-4">{[settings.tagline,settings.tagline_2,settings.tagline_3].map(text=><div key={text} className="flex items-start gap-3"><span className="mt-1 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-[#e4f1ff] text-[#0d55bb]"><Check size={14}/></span><span className="font-semibold text-[#18304f]">{text}</span></div>)}</div></div></div></section><TestimonialSection testimonials={testimonials}/></>}
function ContactPage({settings}:{settings:SiteSettings}){return <><PageHero eyebrow="LET'S TALK TECHNOLOGY" title="A better setup starts with a conversation." desc="Tell us what you need. Our team will recommend the right solution without the jargon." image={settings.hero_image}/><section className="section-pad bg-white"><div className="container grid gap-10 lg:grid-cols-[.8fr_1.2fr]"><div><SectionIntro eyebrow="CONTACT INFORMATION" title="We are here to help." desc="Reach us for a quick quote, a site visit or technical support."/><div className="mt-8 space-y-5"><ContactItem icon={Phone} title="Call us" text={settings.phone} href={`tel:${settings.phone}`}/><ContactItem icon={MessageCircle} title="WhatsApp" text="Chat with our team" href={`https://wa.me/${settings.whatsapp}`}/><ContactItem icon={Mail} title="Email" text={settings.email} href={`mailto:${settings.email}`}/><ContactItem icon={MapPin} title="Location" text={`${settings.city}, ${settings.state}`} /></div></div><ContactForm defaultService=""/></div></section></>}
function ContactItem({icon:Icon,title,text,href}:{icon:LucideIcon;title:string;text:string;href?:string}){const content=<div className="flex items-center gap-4"><span className="flex h-11 w-11 items-center justify-center rounded-lg bg-[#e4f1ff] text-[#0d55bb]"><Icon size={20}/></span><span><b className="block text-sm text-[#071a35]">{title}</b><span className="text-sm text-slate-500">{text}</span></span></div>;return href?<a href={href} target={href.startsWith('http')?'_blank':undefined} rel="noreferrer" className="block hover:opacity-75">{content}</a>:content}
function ContactForm({defaultService}:{defaultService:string}){const [sent,setSent]=useState(false);const [form,setForm]=useState({customer_name:'',phone:'',email:'',service:defaultService,message:''});const update=(key:string,value:string)=>setForm(prev=>({...prev,[key]:value}));const submit=async(e:FormEvent)=>{e.preventDefault();const {error}=await supabase.from('enquiries').insert(form);if(!error)setSent(true);};if(sent)return <div className="flex min-h-[350px] flex-col items-center justify-center rounded-2xl bg-[#effaf4] p-8 text-center"><span className="flex h-16 w-16 items-center justify-center rounded-full bg-[#16834c] text-white"><Check size={28}/></span><h3 className="heading mt-5 text-2xl font-bold text-[#071a35]">Thanks, we got your enquiry.</h3><p className="mt-2 text-slate-600">Our team will get in touch with you shortly.</p></div>;return <form onSubmit={submit} className="rounded-2xl bg-[#eff6ff] p-6 sm:p-8"><h3 className="heading text-2xl font-bold text-[#071a35]">Tell us what you need</h3><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Your name" required value={form.customer_name} onChange={v=>update('customer_name',v)}/><Field label="Phone number" required value={form.phone} onChange={v=>update('phone',v)}/><Field label="Email address" type="email" value={form.email} onChange={v=>update('email',v)}/><Field label="Service you need" value={form.service} onChange={v=>update('service',v)} placeholder="CCTV, laptop repair..."/></div><label className="mt-4 block text-sm font-semibold text-slate-700">Message<textarea required rows={4} value={form.message} onChange={e=>update('message',e.target.value)} className="mt-2 w-full resize-none rounded-lg border border-slate-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#0d55bb]" placeholder="Tell us a little about your requirement..."/></label><button className="mt-5 rounded-lg bg-[#0d55bb] px-6 py-3 text-sm font-bold text-white hover:bg-[#083f8d]">Send enquiry <Send size={15} className="ml-2 inline"/></button></form>}
function Field({label,required,value,onChange,type='text',placeholder}:{label:string;required?:boolean;value:string;onChange:(v:string)=>void;type?:string;placeholder?:string}){return <label className="block text-sm font-semibold text-slate-700">{label}{required&&<span className="text-[#0d55bb]"> *</span>}<input required={required} type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} className="mt-2 w-full rounded-lg border border-slate-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#0d55bb]"/></label>}
function QuoteModal({services,onClose}:{services:Service[];onClose:()=>void}){return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#071a35]/70 p-4 backdrop-blur-sm"><div className="relative max-h-[90vh] w-full max-w-2xl overflow-auto rounded-2xl bg-white"><button onClick={onClose} className="absolute right-4 top-4 rounded-full bg-slate-100 p-2 text-slate-600 hover:bg-slate-200"><X size={18}/></button><div className="p-6 sm:p-8"><p className="text-xs font-bold tracking-widest text-[#0d55bb]">QUICK ENQUIRY</p><h2 className="heading mt-2 text-3xl font-bold text-[#071a35]">Get a tailored quote.</h2><p className="mt-2 text-sm text-slate-500">Share your requirement and our team will call you back.</p><div className="mt-6"><ContactForm defaultService={services[0]?.title??''}/></div></div></div></div>}
function Footer({settings,navigate,onAdmin}:{settings:SiteSettings;navigate:(p:Page)=>void;onAdmin:()=>void}){return <footer className="bg-[#061329] pt-16 text-white"><div className="container grid gap-10 pb-12 md:grid-cols-[1.2fr_.8fr_.8fr] lg:grid-cols-[1.3fr_.8fr_.8fr_.9fr]"><div><div className="flex items-center gap-3"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#0d55bb]"><ShieldCheck size={24}/></span><span><b className="heading block text-lg">{settings.business_name}</b><small className="text-[9px] tracking-widest text-cyan-300">SMART TECHNOLOGY PARTNER</small></span></div><p className="mt-5 max-w-sm text-sm leading-7 text-slate-400">{settings.about_description}</p><div className="mt-6 flex gap-2">{[{icon:Instagram,href:settings.instagram},{icon:Facebook,href:settings.facebook},{icon:Youtube,href:settings.youtube}].map(({icon:Icon,href},i)=><a key={i} href={href||'#'} className="flex h-9 w-9 items-center justify-center rounded-lg border border-white/10 text-slate-400 hover:border-cyan-300 hover:text-cyan-300"><Icon size={16}/></a>)}</div></div><div><h3 className="font-bold">Explore</h3><div className="mt-5 grid gap-3 text-sm text-slate-400">{[['Home','home'],['Services','services'],['CCTV Solutions','cctv'],['Laptop Repair','laptop'],['Networking','networking']].map(([label,value])=><button key={value} onClick={()=>navigate(value as Page)} className="text-left hover:text-cyan-300">{label}</button>)}</div></div><div><h3 className="font-bold">Specialist help</h3><div className="mt-5 grid gap-3 text-sm text-slate-400">{[['Server setup','domain'],['OS installation','os'],['About us','about'],['Contact','contact']].map(([label,value])=><button key={value} onClick={()=>navigate(value as Page)} className="text-left hover:text-cyan-300">{label}</button>)}</div></div><div><h3 className="font-bold">Contact</h3><div className="mt-5 grid gap-4 text-sm text-slate-400"><a href={`tel:${settings.phone}`} className="flex gap-2 hover:text-white"><Phone size={16} className="text-cyan-300"/>{settings.phone}</a><a href={`mailto:${settings.email}`} className="flex gap-2 break-all hover:text-white"><Mail size={16} className="text-cyan-300"/>{settings.email}</a><span className="flex gap-2"><MapPin size={16} className="shrink-0 text-cyan-300"/>{settings.city}, {settings.state}</span></div></div></div><div className="border-t border-white/10"><div className="container flex flex-col justify-between gap-3 py-5 text-xs text-slate-500 sm:flex-row"><span>© {new Date().getFullYear()} {settings.business_name}. All rights reserved.</span><button onClick={onAdmin} className="text-left hover:text-slate-300">Admin access</button></div></div></footer>}
function MobileActions({settings}:{settings:SiteSettings}){return <div className="fixed bottom-4 left-4 right-4 z-30 flex gap-3 sm:hidden"><a href={`tel:${settings.phone}`} className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-[#071a35] py-3 text-sm font-bold text-white shadow-xl"><Phone size={17}/> Call</a><a href={`https://wa.me/${settings.whatsapp}`} target="_blank" rel="noreferrer" className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-[#16834c] py-3 text-sm font-bold text-white shadow-xl"><MessageCircle size={17}/> WhatsApp</a></div>}

function AdminApp({settings,setSettings,services,setServices,products,setProducts,categories,setCategories,laptopServices,setLaptopServices,enquiries,setEnquiries,news,setNews,testimonials,setTestimonials,faqs,setFaqs,adminView,setAdminView,session,setSession}:{settings:SiteSettings;setSettings:(s:SiteSettings)=>void;services:Service[];setServices:(s:Service[])=>void;products:CctvProduct[];setProducts:(p:CctvProduct[])=>void;categories:CctvCategory[];setCategories:(c:CctvCategory[])=>void;laptopServices:LaptopService[];setLaptopServices:(l:LaptopService[])=>void;enquiries:Enquiry[];setEnquiries:(e:Enquiry[])=>void;news:NewsItem[];setNews:(n:NewsItem[])=>void;testimonials:Testimonial[];setTestimonials:(t:Testimonial[])=>void;faqs:Faq[];setFaqs:(f:Faq[])=>void;adminView:AdminView;setAdminView:(v:AdminView)=>void;session:boolean;setSession:(v:boolean)=>void}){if(!session)return <AdminLogin onSuccess={()=>setSession(true)}/>;return <div className="min-h-screen bg-[#f4f7fb] text-[#122034]"><AdminSidebar view={adminView} setView={setAdminView} onLogout={async()=>{await supabase.auth.signOut();setSession(false)}}/><div className="lg:pl-64"><div className="flex h-20 items-center justify-between border-b border-slate-200 bg-white px-5 sm:px-8"><div><p className="text-xs font-bold tracking-widest text-[#0d55bb]">MS INFOTECH ADMIN</p><h1 className="heading text-xl font-bold text-[#071a35]">{adminView==='dashboard'?'Good morning, admin.':adminView==='categories'?'CCTV categories':adminView==='laptop'?'Laptop services':adminView.charAt(0).toUpperCase()+adminView.slice(1)}</h1></div><div className="flex items-center gap-3"><a href="/" className="hidden rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-600 hover:border-[#0d55bb] hover:text-[#0d55bb] sm:block">View website</a><span className="flex h-10 w-10 items-center justify-center rounded-full bg-[#e4f1ff] text-[#0d55bb]"><User size={18}/></span></div></div><div className="p-5 sm:p-8">{adminView==='dashboard'&&<AdminDashboard settings={settings} services={services} products={products} enquiries={enquiries} news={news}/>} {adminView==='settings'&&<SettingsPanel settings={settings} setSettings={setSettings}/>} {adminView==='services'&&<ServicesPanel services={services} setServices={setServices}/>} {adminView==='products'&&<ProductsPanel products={products} setProducts={setProducts}/>} {adminView==='categories'&&<CategoriesPanel categories={categories} setCategories={setCategories}/>} {adminView==='laptop'&&<LaptopPanel laptopServices={laptopServices} setLaptopServices={setLaptopServices}/>} {adminView==='enquiries'&&<EnquiriesPanel enquiries={enquiries} setEnquiries={setEnquiries}/>} {adminView==='news'&&<NewsPanel news={news} setNews={setNews}/>} {adminView==='media'&&<MediaPanel/>} {adminView==='testimonials'&&<TestimonialsPanel testimonials={testimonials} setTestimonials={setTestimonials}/>} {adminView==='faqs'&&<FaqPanel faqs={faqs} setFaqs={setFaqs}/>}</div></div></div>}
function AdminSidebar({view,setView,onLogout}:{view:AdminView;setView:(v:AdminView)=>void;onLogout:()=>void}){const items:{label:string;value:AdminView;icon:LucideIcon}[]=[{label:'Dashboard',value:'dashboard',icon:Gauge},{label:'Website settings',value:'settings',icon:Settings},{label:'Services',value:'services',icon:Package},{label:'CCTV products',value:'products',icon:Camera},{label:'CCTV categories',value:'categories',icon:Eye},{label:'Laptop services',value:'laptop',icon:Laptop},{label:'Customer enquiries',value:'enquiries',icon:ClipboardList},{label:'News & updates',value:'news',icon:Bell},{label:'Media library',value:'media',icon:Image},{label:'Testimonials',value:'testimonials',icon:Quote},{label:'FAQs',value:'faqs',icon:FileText}];return <aside className="fixed inset-y-0 left-0 z-40 hidden w-64 flex-col bg-[#071a35] text-white lg:flex"><div className="flex h-20 items-center gap-3 border-b border-white/10 px-6"><span className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#0d55bb]"><ShieldCheck size={22}/></span><div><b className="heading block">MS INFOTECH</b><small className="text-[9px] tracking-widest text-cyan-300">ADMIN PANEL</small></div></div><nav className="flex-1 overflow-auto p-4">{items.map(item=><button key={item.value} onClick={()=>setView(item.value)} className={`mb-1 flex w-full items-center gap-3 rounded-lg px-3 py-3 text-sm font-semibold transition ${view===item.value?'bg-[#0d55bb] text-white':'text-slate-400 hover:bg-white/5 hover:text-white'}`}><item.icon size={17}/>{item.label}</button>)}</nav><div className="border-t border-white/10 p-4"><button onClick={onLogout} className="flex w-full items-center gap-3 rounded-lg px-3 py-3 text-sm font-semibold text-slate-400 hover:bg-white/5 hover:text-white"><LogOut size={17}/> Log out</button></div></aside>}
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LegacyAdminLogin({onSuccess}:{onSuccess:()=>void}){const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');const {error:authError}=await supabase.auth.signInWithPassword({email,password});if(authError)setError('The email or password is not correct.');else onSuccess();setBusy(false);};return <div className="flex min-h-screen items-center justify-center bg-[#071a35] p-5"><div className="grid w-full max-w-4xl overflow-hidden rounded-2xl bg-white shadow-2xl lg:grid-cols-2"><div className="relative hidden min-h-[560px] overflow-hidden bg-[#0d55bb] p-10 text-white lg:block"><div className="absolute inset-0 bg-cover bg-center opacity-25" style={{backgroundImage:`url(${img+'37730212/pexels-photo-37730212.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'})`}}/><div className="relative flex h-full flex-col justify-between"><div><span className="flex h-12 w-12 items-center justify-center rounded-xl bg-white/15"><ShieldCheck size={27}/></span><p className="mt-8 text-xs font-bold tracking-[.2em] text-cyan-200">SECURE WORKSPACE</p><h1 className="heading mt-4 text-4xl font-bold leading-tight">Your business,<br/>beautifully managed.</h1></div><p className="max-w-xs text-sm leading-6 text-blue-100">Manage your website, services, products and enquiries from one secure place.</p></div></div><form onSubmit={submit} className="p-8 sm:p-12"><a href="/" className="text-sm font-semibold text-[#0d55bb]">← Back to website</a><div className="mt-14"><p className="text-xs font-bold tracking-[.2em] text-[#0d55bb]">ADMIN ACCESS</p><h2 className="heading mt-3 text-3xl font-bold text-[#071a35]">Welcome back.</h2><p className="mt-2 text-sm text-slate-500">Sign in to manage your MS INFOTECH website.</p></div><label className="mt-8 block text-sm font-semibold text-slate-700">Email address<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} className="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 outline-none focus:border-[#0d55bb]" placeholder="admin@example.com"/></label><label className="mt-4 block text-sm font-semibold text-slate-700">Password<input required type="password" value={password} onChange={e=>setPassword(e.target.value)} className="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 outline-none focus:border-[#0d55bb]" placeholder="Your password"/></label>{error&&<p className="mt-4 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}<button disabled={busy} className="mt-6 w-full rounded-lg bg-[#0d55bb] py-3.5 text-sm font-bold text-white hover:bg-[#083f8d] disabled:opacity-60">{busy?'Signing in...':'Sign in'} <ArrowRight size={15} className="ml-1 inline"/></button><p className="mt-6 text-center text-xs text-slate-400"><Lock size={12} className="mr-1 inline"/> Secure password-protected area</p></form></div></div>}
const ADMIN_EMAIL='admin@msinfotech.com';
function AdminLogin({onSuccess}:{onSuccess:()=>void}){const [password,setPassword]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');const {error:authError}=await supabase.auth.signInWithPassword({email:ADMIN_EMAIL,password});if(authError)setError('Incorrect password. Please try again.');else onSuccess();setBusy(false);};return <div className="flex min-h-screen items-center justify-center bg-[#071a35] p-5"><div className="grid w-full max-w-4xl overflow-hidden rounded-2xl bg-white shadow-2xl lg:grid-cols-2"><div className="relative hidden min-h-[560px] overflow-hidden bg-[#0d55bb] p-10 text-white lg:block"><div className="absolute inset-0 bg-cover bg-center opacity-25" style={{backgroundImage:`url(${img+'37730212/pexels-photo-37730212.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'})`}}/><div className="relative flex h-full flex-col justify-between"><div><span className="flex h-12 w-12 items-center justify-center rounded-xl bg-white/15"><ShieldCheck size={27}/></span><p className="mt-8 text-xs font-bold tracking-[.2em] text-cyan-200">SECURE WORKSPACE</p><h1 className="heading mt-4 text-4xl font-bold leading-tight">Your business,<br/>beautifully managed.</h1></div><p className="max-w-xs text-sm leading-6 text-blue-100">Manage your website, services, products and enquiries from one secure place.</p></div></div><form onSubmit={submit} className="p-8 sm:p-12"><a href="/" className="text-sm font-semibold text-[#0d55bb]">← Back to website</a><div className="mt-14"><p className="text-xs font-bold tracking-[.2em] text-[#0d55bb]">ADMIN ACCESS</p><h2 className="heading mt-3 text-3xl font-bold text-[#071a35]">Welcome back.</h2><p className="mt-2 text-sm text-slate-500">Enter your password to manage the MS INFOTECH website.</p></div><label className="mt-8 block text-sm font-semibold text-slate-700">Admin password<input required type="password" value={password} onChange={e=>setPassword(e.target.value)} className="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 outline-none focus:border-[#0d55bb]" placeholder="Enter admin password" autoFocus/></label>{error&&<p className="mt-4 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}<button disabled={busy} className="mt-6 w-full rounded-lg bg-[#0d55bb] py-3.5 text-sm font-bold text-white hover:bg-[#083f8d] disabled:opacity-60">{busy?'Signing in...':'Sign in'} <ArrowRight size={15} className="ml-1 inline"/></button><p className="mt-6 text-center text-xs text-slate-400"><Lock size={12} className="mr-1 inline"/> Secure password-protected area</p></form></div></div>}

function AdminDashboard({settings,services,products,enquiries,news}:{settings:SiteSettings;services:Service[];products:CctvProduct[];enquiries:Enquiry[];news:NewsItem[]}){const stats=[{label:'Total services',value:services.length,icon:Settings,color:'blue'},{label:'CCTV products',value:products.length,icon:Camera,color:'cyan'},{label:'New enquiries',value:enquiries.filter(e=>e.status==='new').length,icon:ClipboardList,color:'green'},{label:'News posts',value:news.length,icon:Bell,color:'amber'}];return <><div className="mb-8 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-sm text-slate-500">Here is what is happening across your site.</p><h2 className="heading mt-1 text-3xl font-bold text-[#071a35]">Overview</h2></div><span className="rounded-lg bg-white px-4 py-2 text-xs font-semibold text-slate-500 shadow-sm">Live website data</span></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map(stat=><div key={stat.label} className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><span className={`flex h-11 w-11 items-center justify-center rounded-lg ${stat.color==='green'?'bg-emerald-50 text-emerald-600':stat.color==='cyan'?'bg-cyan-50 text-cyan-600':stat.color==='amber'?'bg-amber-50 text-amber-600':'bg-blue-50 text-blue-600'}`}><stat.icon size={21}/></span><TrendingUp size={16} className="text-emerald-500"/></div><b className="heading mt-5 block text-3xl text-[#071a35]">{stat.value}</b><span className="mt-1 block text-sm text-slate-500">{stat.label}</span></div>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><div className="rounded-xl border border-slate-200 bg-white p-6"><div className="flex items-center justify-between"><h3 className="heading font-bold text-[#071a35]">Quick actions</h3><Activity size={18} className="text-[#0d55bb]"/></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{['Update contact details','Add a service','Add CCTV product','Review enquiries'].map(item=><div key={item} className="flex items-center justify-between rounded-lg bg-slate-50 p-4 text-sm font-semibold text-slate-700"><span>{item}</span><Plus size={17} className="text-[#0d55bb]"/></div>)}</div></div><div className="rounded-xl bg-[#071a35] p-6 text-white"><p className="text-xs font-bold tracking-widest text-cyan-300">CURRENT BRAND MESSAGE</p><h3 className="heading mt-4 text-2xl font-bold">{settings.tagline_2}</h3><p className="mt-3 text-sm leading-6 text-slate-300">Keep your website content fresh and your customers informed.</p><div className="mt-6 flex items-center gap-2 text-xs text-cyan-200"><BadgeCheck size={16}/> Website is active</div></div></div></>}
function SettingsPanel({settings,setSettings}:{settings:SiteSettings;setSettings:(s:SiteSettings)=>void}){const [draft,setDraft]=useState(settings);const [saved,setSaved]=useState(false);const fields:[keyof SiteSettings,string][]=[['business_name','Business name'],['phone','Phone number'],['whatsapp','WhatsApp number'],['email','Email address'],['address','Address'],['city','City'],['state','State'],['pincode','PIN code'],['business_hours','Business hours'],['hero_title','Hero title'],['hero_subtitle','Hero subtitle'],['hero_description','Hero description'],['hero_image','Hero image URL'],['about_title','About title'],['cctv_section_title','CCTV section title'],['laptop_section_title','Laptop section title'],['networking_section_title','Networking section title'],['domain_section_title','Domain section title'],['os_section_title','OS section title'],['instagram','Instagram URL'],['facebook','Facebook URL'],['youtube','YouTube URL'],['linkedin','LinkedIn URL'],['seo_title','SEO title'],['seo_description','SEO description']];const save=async()=>{const {error}=await supabase.from('site_settings').update(draft).eq('id',1);if(!error){setSettings(draft);setSaved(true);setTimeout(()=>setSaved(false),2500);}};return <AdminCard title="Website settings" description="Update the information customers see across your website."><div className="grid gap-4 sm:grid-cols-2">{fields.map(([key,label])=><label key={key} className="text-sm font-semibold text-slate-700">{label}<input value={String(draft[key]??'')} onChange={e=>setDraft({...draft,[key]:e.target.value})} className="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 outline-none focus:border-[#0d55bb]"/></label>)}</div><label className="mt-4 block text-sm font-semibold text-slate-700">About description<textarea rows={4} value={draft.about_description} onChange={e=>setDraft({...draft,about_description:e.target.value})} className="mt-2 w-full rounded-lg border border-slate-200 px-4 py-3 outline-none focus:border-[#0d55bb]"/></label><button onClick={save} className="mt-6 rounded-lg bg-[#0d55bb] px-5 py-3 text-sm font-bold text-white"><Save size={15} className="mr-2 inline"/>{saved?'Saved':'Save changes'}</button></AdminCard>}
function AdminCard({title,description,children,addLabel,onAdd}:{title:string;description:string;children:ReactNode;addLabel?:string;onAdd?:()=>void}){return <div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><div className="mb-7 flex items-start justify-between gap-4"><div><h2 className="heading text-2xl font-bold text-[#071a35]">{title}</h2><p className="mt-1 text-sm text-slate-500">{description}</p></div>{onAdd&&<button onClick={onAdd} className="hidden rounded-lg bg-[#0d55bb] px-4 py-2.5 text-sm font-bold text-white sm:block"><Plus size={15} className="mr-1 inline"/> {addLabel||'Add new'}</button>}</div>{children}</div>}
function ServicesPanel({services,setServices}:{services:Service[];setServices:(s:Service[])=>void}){const [editing,setEditing]=useState<Service|null>(null);const [adding,setAdding]=useState(false);const blank:Service={id:'new',title:'',slug:'',short_description:'',long_description:'',icon:'Settings',image:'',features:[],category:'core',sort_order:services.length+1,is_published:true};const save=async()=>{if(!editing)return;const payload={title:editing.title,slug:editing.slug||editing.title.toLowerCase().replace(/ /g,'-'),short_description:editing.short_description,long_description:editing.long_description,icon:editing.icon,image:editing.image,features:editing.features,category:editing.category,sort_order:editing.sort_order,is_published:editing.is_published};const result=editing.id.startsWith('new')?await supabase.from('services').insert(payload).select().single():await supabase.from('services').update(payload).eq('id',editing.id).select().single();if(!result.error&&result.data){setServices(services.some(x=>x.id===editing.id)?services.map(x=>x.id===editing.id?result.data as Service:x):[...services,result.data as Service]);setEditing(null);setAdding(false);}};const remove=async(id:string)=>{await supabase.from('services').delete().eq('id',id);setServices(services.filter(s=>s.id!==id));};return <AdminCard title="Services" description="Manage the service cards displayed on your website." addLabel="Add service" onAdd={()=>{setEditing({...blank});setAdding(true);}}><div className="divide-y divide-slate-100">{services.map(service=><div key={service.id} className="flex items-center gap-4 py-4"><img src={service.image} alt="" className="h-14 w-20 rounded-lg object-cover"/><div className="min-w-0 flex-1"><b className="block font-semibold text-[#071a35]">{service.title}</b><span className="block truncate text-sm text-slate-500">{service.short_description}</span></div><button onClick={()=>{setEditing(service);setAdding(false);}} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-bold text-[#0d55bb]">Edit</button><button onClick={()=>void remove(service.id)} className="rounded-lg p-2 text-red-500 hover:bg-red-50"><Trash2 size={16}/></button></div>)}</div>{editing&&<EditService service={editing} setService={setEditing} onSave={save} onClose={()=>{setEditing(null);setAdding(false);}} adding={adding}/>}</AdminCard>}
function EditService({service,setService,onSave,onClose,adding}:{service:Service;setService:(s:Service)=>void;onSave:()=>void;onClose:()=>void;adding?:boolean}){const [featText,setFeatText]=useState('');const addFeat=()=>{if(featText.trim()){setService({...service,features:[...service.features,featText.trim()]});setFeatText('');}};return <div className="mt-6 rounded-xl bg-[#eff6ff] p-5"><div className="flex justify-between"><h3 className="heading font-bold">{adding?'Add service':'Edit service'}</h3><button onClick={onClose}><X size={18}/></button></div>{service.image&&<img src={service.image} alt="preview" className="mt-4 h-32 w-full rounded-lg object-cover"/>}<div className="mt-4 grid gap-3 sm:grid-cols-2"><input value={service.title} onChange={e=>setService({...service,title:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Title"/><input value={service.slug} onChange={e=>setService({...service,slug:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Slug (auto-generated if empty)"/><input value={service.icon} onChange={e=>setService({...service,icon:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Icon name (e.g. Camera, Laptop, Server)"/><input value={service.image} onChange={e=>setService({...service,image:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Image URL"/></div><textarea value={service.short_description} onChange={e=>setService({...service,short_description:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Short description" rows={2}/><textarea value={service.long_description} onChange={e=>setService({...service,long_description:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Long description" rows={3}/><div className="mt-3"><label className="text-sm font-semibold text-slate-700">Features</label><div className="mt-2 flex gap-2"><input value={featText} onChange={e=>setFeatText(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();addFeat();}}} className="flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Add a feature and press Enter"/><button type="button" onClick={addFeat} className="rounded-lg bg-[#0d55bb] px-3 py-2 text-sm font-bold text-white">Add</button></div><div className="mt-2 flex flex-wrap gap-2">{service.features.map((f,i)=><span key={i} className="flex items-center gap-1 rounded bg-white px-2 py-1 text-xs font-semibold text-slate-700">{f}<button onClick={()=>setService({...service,features:service.features.filter((_,j)=>j!==i)})}><X size={12} className="text-red-400"/></button></span>)}</div></div><button onClick={onSave} className="mt-4 rounded-lg bg-[#0d55bb] px-4 py-2 text-sm font-bold text-white">{adding?'Add service':'Save service'}</button></div>}
function ProductsPanel({products,setProducts}:{products:CctvProduct[];setProducts:(p:CctvProduct[])=>void}){const [items,setItems]=useState<CctvProduct[]>(products);const [editing,setEditing]=useState<CctvProduct|null>(null);const [adding,setAdding]=useState(false);useEffect(()=>{void supabase.from('cctv_products').select('*').order('sort_order').then(({data})=>{if(data)setItems(data as CctvProduct[]);});},[]);const blank:CctvProduct={id:'new',name:'',brand:'',model:'',image:'',gallery:[],video_url:'',description:'',features:[],specifications:{},resolution:'',night_vision:'',storage_support:'',warranty:'',price:0,discount_price:0,stock_status:'in_stock',installation_available:true,is_published:true};const save=async()=>{if(!editing)return;const payload={name:editing.name,brand:editing.brand,model:editing.model,image:editing.image,description:editing.description,features:editing.features,price:editing.price,discount_price:editing.discount_price,stock_status:editing.stock_status,resolution:editing.resolution,night_vision:editing.night_vision,storage_support:editing.storage_support,warranty:editing.warranty,installation_available:editing.installation_available,is_published:editing.is_published,sort_order:items.length+1};const result=editing.id.startsWith('new')?await supabase.from('cctv_products').insert(payload).select().single():await supabase.from('cctv_products').update(payload).eq('id',editing.id).select().single();if(!result.error&&result.data){setItems(items.some(x=>x.id===editing.id)?items.map(x=>x.id===editing.id?result.data as CctvProduct:x):[...items,result.data as CctvProduct]);setProducts(items.some(x=>x.id===editing.id)?items.map(x=>x.id===editing.id?result.data as CctvProduct:x):[...items,result.data as CctvProduct]);setEditing(null);setAdding(false);}};const remove=async(id:string)=>{await supabase.from('cctv_products').delete().eq('id',id);setItems(items.filter(p=>p.id!==id));setProducts(items.filter(p=>p.id!==id));};return <AdminCard title="CCTV products" description="Manage cameras, recorders, accessories and pricing." addLabel="Add product" onAdd={()=>{setEditing({...blank});setAdding(true);}}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{items.map(product=><div key={product.id} className="overflow-hidden rounded-xl border border-slate-200"><img src={product.image} alt={product.name} className="h-36 w-full object-cover"/><div className="p-4"><b className="block font-semibold text-[#071a35]">{product.name}</b><span className="mt-1 block text-sm text-slate-500">{product.brand} · {product.model}</span><div className="mt-3 flex items-center justify-between"><b className="text-[#0d55bb]">₹{(product.discount_price||product.price).toLocaleString('en-IN')}</b><span className="rounded-full bg-emerald-50 px-2 py-1 text-[10px] font-bold text-emerald-700">{product.stock_status.replace('_',' ')}</span></div><div className="mt-3 flex gap-2"><button onClick={()=>{setEditing(product);setAdding(false);}} className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-bold text-[#0d55bb]">Edit</button><button onClick={()=>void remove(product.id)} className="rounded-lg p-1.5 text-red-500 hover:bg-red-50"><Trash2 size={15}/></button></div></div></div>)}</div>{!items.length&&<p className="rounded-lg bg-slate-50 p-6 text-sm text-slate-500">No products yet. Add your first CCTV product to show it here.</p>}{editing&&<EditProduct product={editing} setProduct={setEditing} onSave={save} onClose={()=>{setEditing(null);setAdding(false);}} adding={adding}/>}</AdminCard>}
function EditProduct({product,setProduct,onSave,onClose,adding}:{product:CctvProduct;setProduct:(p:CctvProduct)=>void;onSave:()=>void;onClose:()=>void;adding?:boolean}){const [featText,setFeatText]=useState('');const addFeat=()=>{if(featText.trim()){setProduct({...product,features:[...product.features,featText.trim()]});setFeatText('');}};return <div className="mt-6 rounded-xl bg-[#eff6ff] p-5"><div className="flex justify-between"><h3 className="heading font-bold">{adding?'Add product':'Edit product'}</h3><button onClick={onClose}><X size={18}/></button></div>{product.image&&<img src={product.image} alt="preview" className="mt-4 h-40 w-full rounded-lg object-cover"/>}<div className="mt-4 grid gap-3 sm:grid-cols-2"><input value={product.name} onChange={e=>setProduct({...product,name:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Product name"/><input value={product.brand} onChange={e=>setProduct({...product,brand:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Brand"/><input value={product.model} onChange={e=>setProduct({...product,model:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Model"/><input value={product.image} onChange={e=>setProduct({...product,image:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Image URL"/><input type="number" value={product.price} onChange={e=>setProduct({...product,price:Number(e.target.value)})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Price (₹)"/><input type="number" value={product.discount_price} onChange={e=>setProduct({...product,discount_price:Number(e.target.value)})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Discount price (₹)"/><input value={product.resolution} onChange={e=>setProduct({...product,resolution:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Resolution"/><input value={product.night_vision} onChange={e=>setProduct({...product,night_vision:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Night vision"/><input value={product.storage_support} onChange={e=>setProduct({...product,storage_support:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Storage support"/><input value={product.warranty} onChange={e=>setProduct({...product,warranty:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Warranty"/><select value={product.stock_status} onChange={e=>setProduct({...product,stock_status:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm"><option value="in_stock">In stock</option><option value="out_of_stock">Out of stock</option><option value="pre_order">Pre-order</option></select></div><textarea value={product.description} onChange={e=>setProduct({...product,description:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Description" rows={3}/><div className="mt-3"><label className="text-sm font-semibold text-slate-700">Features</label><div className="mt-2 flex gap-2"><input value={featText} onChange={e=>setFeatText(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();addFeat();}}} className="flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Add a feature and press Enter"/><button type="button" onClick={addFeat} className="rounded-lg bg-[#0d55bb] px-3 py-2 text-sm font-bold text-white">Add</button></div><div className="mt-2 flex flex-wrap gap-2">{product.features.map((f,i)=><span key={i} className="flex items-center gap-1 rounded bg-white px-2 py-1 text-xs font-semibold text-slate-700">{f}<button onClick={()=>setProduct({...product,features:product.features.filter((_,j)=>j!==i)})}><X size={12} className="text-red-400"/></button></span>)}</div></div><button onClick={onSave} className="mt-4 rounded-lg bg-[#0d55bb] px-4 py-2 text-sm font-bold text-white">{adding?'Add product':'Save product'}</button></div>}
function EnquiriesPanel({enquiries,setEnquiries}:{enquiries:Enquiry[];setEnquiries:(e:Enquiry[])=>void}){const [expanded,setExpanded]=useState<string|null>(null);useEffect(()=>{void supabase.from('enquiries').select('*').order('created_at',{ascending:false}).then(({data})=>{if(data)setEnquiries(data as Enquiry[]);});},[setEnquiries]);const update=async(id:string,status:string)=>{await supabase.from('enquiries').update({status}).eq('id',id);setEnquiries(enquiries.map(item=>item.id===id?{...item,status}:item));};const remove=async(id:string)=>{await supabase.from('enquiries').delete().eq('id',id);setEnquiries(enquiries.filter(item=>item.id!==id));};return <AdminCard title="Customer enquiries" description="Track every request from the website and follow up with confidence."><div className="overflow-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead><tr className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-400"><th className="pb-3">Customer</th><th className="pb-3">Requirement</th><th className="pb-3">Date</th><th className="pb-3">Status</th><th className="pb-3">Actions</th></tr></thead><tbody>{enquiries.map(item=><><tr key={item.id} className="cursor-pointer border-b border-slate-100" onClick={()=>setExpanded(expanded===item.id?null:item.id)}><td className="py-4"><b className="block text-[#071a35]">{item.customer_name}</b><span className="text-xs text-slate-500">{item.phone}</span></td><td className="py-4 text-slate-600">{item.service||'General enquiry'}</td><td className="py-4 text-slate-500">{new Date(item.created_at).toLocaleDateString('en-IN')}</td><td className="py-4"><select value={item.status} onClick={e=>e.stopPropagation()} onChange={e=>void update(item.id,e.target.value)} className="rounded-lg border border-slate-200 px-2 py-1.5 text-xs"><option value="new">New</option><option value="contacted">Contacted</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></td><td className="py-4" onClick={e=>e.stopPropagation()}><a href={`tel:${item.phone}`} className="mr-2 rounded-lg bg-[#e4f1ff] px-3 py-2 text-xs font-bold text-[#0d55bb]">Call</a><a href={`https://wa.me/${item.phone.replace(/\D/g,'')}`} target="_blank" rel="noreferrer" className="mr-2 rounded-lg bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-700">WhatsApp</a><button onClick={()=>void remove(item.id)} className="rounded-lg p-2 text-red-500 hover:bg-red-50"><Trash2 size={15}/></button></td></tr>{expanded===item.id&&<tr className="bg-slate-50"><td colSpan={5} className="px-4 py-4"><div className="grid gap-2 text-sm text-slate-600"><span><b className="text-slate-400">Email:</b> {item.email||'—'}</span><span><b className="text-slate-400">Location:</b> {item.location||'—'}</span><span><b className="text-slate-400">Product:</b> {item.product||'—'}</span><span><b className="text-slate-400">Message:</b> {item.message||'—'}</span></div></td></tr>}</>)}</tbody></table>{!enquiries.length&&<p className="py-8 text-center text-sm text-slate-500">No customer enquiries yet.</p>}</div></AdminCard>}
function NewsPanel({news,setNews}:{news:NewsItem[];setNews:(n:NewsItem[])=>void}){const [items,setItems]=useState<NewsItem[]>(news);const [editing,setEditing]=useState<NewsItem|null>(null);const [adding,setAdding]=useState(false);useEffect(()=>{void supabase.from('news').select('*').order('news_date',{ascending:false}).then(({data})=>{if(data)setItems(data as NewsItem[]);});},[]);const blank:NewsItem={id:'new',title:'',description:'',image:'',news_date:new Date().toISOString().slice(0,10),is_published:true};const save=async()=>{if(!editing)return;const payload={title:editing.title,description:editing.description,image:editing.image,news_date:editing.news_date,is_published:editing.is_published};const result=editing.id.startsWith('new')?await supabase.from('news').insert(payload).select().single():await supabase.from('news').update(payload).eq('id',editing.id).select().single();if(!result.error&&result.data){setItems(items.some(x=>x.id===editing.id)?items.map(x=>x.id===editing.id?result.data as NewsItem:x):[result.data as NewsItem,...items]);setNews(items.some(x=>x.id===editing.id)?items.map(x=>x.id===editing.id?result.data as NewsItem:x):[result.data as NewsItem,...items]);setEditing(null);setAdding(false);}};const remove=async(id:string)=>{await supabase.from('news').delete().eq('id',id);setItems(items.filter(n=>n.id!==id));setNews(items.filter(n=>n.id!==id));};return <AdminCard title="News & updates" description="Keep customers informed with the latest from your business." addLabel="Add post" onAdd={()=>{setEditing({...blank});setAdding(true);}}><div className="grid gap-4 md:grid-cols-2">{items.map(item=><div key={item.id} className="flex gap-4 rounded-xl border border-slate-200 p-4"><img src={item.image} alt="" className="h-20 w-24 rounded-lg object-cover"/><div className="flex-1"><b className="block text-[#071a35]">{item.title}</b><span className="mt-1 block text-xs text-slate-500">{new Date(item.news_date).toLocaleDateString('en-IN')}</span><div className="mt-2 flex gap-2"><button onClick={()=>{setEditing(item);setAdding(false);}} className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-bold text-[#0d55bb]">Edit</button><button onClick={()=>void remove(item.id)} className="rounded-lg p-1.5 text-red-500 hover:bg-red-50"><Trash2 size={15}/></button></div></div></div>)}</div>{!items.length&&<p className="rounded-lg bg-slate-50 p-6 text-sm text-slate-500">No news posts yet.</p>}{editing&&<EditNews item={editing} setItem={setEditing} onSave={save} onClose={()=>{setEditing(null);setAdding(false);}} adding={adding}/>}</AdminCard>}
function EditNews({item,setItem,onSave,onClose,adding}:{item:NewsItem;setItem:(n:NewsItem)=>void;onSave:()=>void;onClose:()=>void;adding?:boolean}){return <div className="mt-6 rounded-xl bg-[#eff6ff] p-5"><div className="flex justify-between"><h3 className="heading font-bold">{adding?'Add news post':'Edit news post'}</h3><button onClick={onClose}><X size={18}/></button></div>{item.image&&<img src={item.image} alt="preview" className="mt-4 h-32 w-full rounded-lg object-cover"/>}<div className="mt-4 grid gap-3"><input value={item.title} onChange={e=>setItem({...item,title:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Title"/><input value={item.image} onChange={e=>setItem({...item,image:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Image URL"/><input type="date" value={item.news_date} onChange={e=>setItem({...item,news_date:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm"/><textarea value={item.description} onChange={e=>setItem({...item,description:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Description" rows={3}/></div><button onClick={onSave} className="mt-4 rounded-lg bg-[#0d55bb] px-4 py-2 text-sm font-bold text-white">{adding?'Add post':'Save post'}</button></div>}
function MediaPanel(){const [items,setItems]=useState<{id:string;url:string;title:string;category:string;alt_text:string}[]>([]);const [form,setForm]=useState({url:'',title:'',category:'Homepage',alt_text:''});const [editingId,setEditingId]=useState<string|null>(null);const [editForm,setEditForm]=useState({url:'',title:'',category:'Homepage',alt_text:''});const [message,setMessage]=useState('');useEffect(()=>{void supabase.from('media').select('id,url,title,category,alt_text').eq('type','image').order('created_at',{ascending:false}).then(({data})=>{if(data)setItems(data as typeof items);});},[]);const add=async()=>{if(!form.url.trim())return;const {data,error}=await supabase.from('media').insert({type:'image',...form}).select('id,url,title,category,alt_text').single();if(!error&&data){setItems([data as typeof items[number],...items]);setForm({url:'',title:'',category:'Homepage',alt_text:''});setMessage('Image added');setTimeout(()=>setMessage(''),2000);}};const startEdit=(item:{id:string;url:string;title:string;category:string;alt_text:string})=>{setEditingId(item.id);setEditForm({url:item.url,title:item.title,category:item.category,alt_text:item.alt_text});};const saveEdit=async()=>{if(!editingId)return;const {data,error}=await supabase.from('media').update(editForm).eq('id',editingId).select('id,url,title,category,alt_text').single();if(!error&&data){setItems(items.map(i=>i.id===editingId?data as typeof items[number]:i));setEditingId(null);}};const remove=async(id:string)=>{await supabase.from('media').delete().eq('id',id);setItems(items.filter(item=>item.id!==id));};return <AdminCard title="Media library" description="Manage image URLs used throughout the website."><div className="grid gap-3 rounded-xl bg-[#eff6ff] p-4 sm:grid-cols-[1.5fr_1fr_1fr_auto]"><input value={form.url} onChange={e=>setForm({...form,url:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Image URL"/><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Title"/><select value={form.category} onChange={e=>setForm({...form,category:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm"><option>Homepage</option><option>CCTV</option><option>Laptop Repair</option><option>Networking</option><option>Servers</option><option>Gallery</option></select><button onClick={()=>void add()} className="rounded-lg bg-[#0d55bb] px-4 py-2 text-sm font-bold text-white"><Plus size={15} className="mr-1 inline"/>Add</button></div>{message&&<p className="mt-3 text-sm text-emerald-700">{message}</p>}<div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{items.map(item=>editingId===item.id?<div key={item.id} className="rounded-xl bg-[#eff6ff] p-4"><div className="flex justify-between"><h4 className="text-sm font-bold text-[#071a35]">Edit image</h4><button onClick={()=>setEditingId(null)}><X size={16}/></button></div><input value={editForm.url} onChange={e=>setEditForm({...editForm,url:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="URL"/><input value={editForm.title} onChange={e=>setEditForm({...editForm,title:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Title"/><select value={editForm.category} onChange={e=>setEditForm({...editForm,category:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm"><option>Homepage</option><option>CCTV</option><option>Laptop Repair</option><option>Networking</option><option>Servers</option><option>Gallery</option></select><input value={editForm.alt_text} onChange={e=>setEditForm({...editForm,alt_text:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Alt text"/><button onClick={saveEdit} className="mt-3 rounded-lg bg-[#0d55bb] px-4 py-2 text-sm font-bold text-white">Save</button></div>:<div key={item.id} className="overflow-hidden rounded-xl border border-slate-200"><img src={item.url} alt={item.alt_text||item.title} className="h-36 w-full object-cover"/><div className="flex items-center justify-between gap-3 p-3"><div className="min-w-0"><b className="block truncate text-sm text-[#071a35]">{item.title||'Untitled image'}</b><span className="text-xs text-slate-500">{item.category}</span></div><div className="flex gap-1"><button onClick={()=>startEdit(item)} className="rounded-lg border border-slate-200 px-2 py-1 text-xs font-bold text-[#0d55bb]">Edit</button><button onClick={()=>void remove(item.id)} className="rounded-lg p-2 text-red-500 hover:bg-red-50"><Trash2 size={15}/></button></div></div></div>)}</div>{!items.length&&<p className="mt-6 rounded-lg bg-slate-50 p-6 text-sm text-slate-500">No images added yet.</p>}</AdminCard>}
function TestimonialsPanel({testimonials,setTestimonials}:{testimonials:Testimonial[];setTestimonials:(t:Testimonial[])=>void}){const [items,setItems]=useState<Testimonial[]>(testimonials);const [editing,setEditing]=useState<Testimonial|null>(null);const [adding,setAdding]=useState(false);useEffect(()=>{void supabase.from('testimonials').select('*').order('created_at',{ascending:false}).then(({data})=>{if(data)setItems(data as Testimonial[]);});},[]);const blank:Testimonial={id:'new',customer_name:'',rating:5,message:'',image:'',is_published:true};const save=async()=>{if(!editing)return;const payload={customer_name:editing.customer_name,rating:editing.rating,message:editing.message,image:editing.image,is_published:editing.is_published};const result=editing.id.startsWith('new')?await supabase.from('testimonials').insert(payload).select().single():await supabase.from('testimonials').update(payload).eq('id',editing.id).select().single();if(!result.error&&result.data){const updated=items.some(x=>x.id===editing.id)?items.map(x=>x.id===editing.id?result.data as Testimonial:x):[result.data as Testimonial,...items];setItems(updated);setTestimonials(updated);setEditing(null);setAdding(false);}};const remove=async(id:string)=>{await supabase.from('testimonials').delete().eq('id',id);const updated=items.filter(item=>item.id!==id);setItems(updated);setTestimonials(updated);};return <AdminCard title="Testimonials" description="Showcase feedback from happy customers." addLabel="Add testimonial" onAdd={()=>{setEditing({...blank});setAdding(true);}}><div className="mt-6 grid gap-4 md:grid-cols-2">{items.map(item=><div key={item.id} className="rounded-xl border border-slate-200 p-5"><div className="flex items-start justify-between"><span className="font-bold text-[#071a35]">{item.customer_name}</span><div className="flex gap-2"><button onClick={()=>{setEditing(item);setAdding(false);}} className="rounded-lg border border-slate-200 px-2 py-1 text-xs font-bold text-[#0d55bb]">Edit</button><button onClick={()=>void remove(item.id)} className="text-red-500"><Trash2 size={16}/></button></div></div><div className="mt-2 flex text-amber-400">{Array.from({length:item.rating}).map((_,i)=><Star key={i} size={14} fill="currentColor"/>)}</div><p className="mt-3 text-sm leading-6 text-slate-600">{item.message}</p></div>)}</div>{!items.length&&<p className="mt-6 rounded-lg bg-slate-50 p-6 text-sm text-slate-500">No testimonials yet.</p>}{editing&&<div className="mt-6 rounded-xl bg-[#eff6ff] p-5"><div className="flex justify-between"><h3 className="heading font-bold">{adding?'Add testimonial':'Edit testimonial'}</h3><button onClick={()=>{setEditing(null);setAdding(false);}}><X size={18}/></button></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><input value={editing.customer_name} onChange={e=>setEditing({...editing,customer_name:e.target.value})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Customer name"/><select value={editing.rating} onChange={e=>setEditing({...editing,rating:Number(e.target.value)})} className="rounded-lg border border-slate-200 px-3 py-2 text-sm"><option value={5}>5 stars</option><option value={4}>4 stars</option><option value={3}>3 stars</option><option value={2}>2 stars</option><option value={1}>1 star</option></select></div><textarea value={editing.message} onChange={e=>setEditing({...editing,message:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Testimonial message" rows={3}/><input value={editing.image} onChange={e=>setEditing({...editing,image:e.target.value})} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm" placeholder="Image URL (optional)"/><button onClick={save} className="mt-4 rounded-lg bg-[#0d55bb] px-4 py-2 text-sm font-bold text-white">{adding?'Add testimonial':'Save testimonial'}</button></div>}</AdminCard>}
